INSERT INTO role_permissions(role_id,permission_id,scope) SELECT r.id,p.id,g.scope FROM grants g JOIN roles r ON r.code=g.role_code CROSS JOIN LATERAL unnest(g.codes) c JOIN permissions p ON p.code=c ON CONFLICT(role_id,permission_id) DO NOTHING;
