INSERT INTO task_rules(code,trigger_event,title_template,owner_role_id,due_minutes,auto_close_event,suggested) SELECT d.code,d.event,d.title,r.id,d.due,d.close_event,d.suggested FROM defaults d JOIN roles r ON r.code=d.role_code;
-- Refuse ambiguous legacy mappings instead of discarding any membership.
DO $$ BEGIN
 IF EXISTS(SELECT customer_id FROM booking_lab_memberships WHERE active=1 GROUP BY customer_id HAVING count(*)>1) THEN RAISE EXCEPTION 'Legacy customers have multiple companies; explicit mapping required'; END IF;
 IF EXISTS(SELECT 1 FROM staff_users s JOIN booking_lab_customers c ON lower(c.email)=lower(s.email)) THEN RAISE EXCEPTION 'A legacy email is both staff and customer; resolve mapping first'; END IF;
END $$;
INSERT INTO users(email,display_name,kind,state,staff_user_id,created_at,updated_at) SELECT lower(email),name,'staff',CASE WHEN active=1 THEN 'active' ELSE 'disabled' END,id,to_timestamp(created_at/1000.0),to_timestamp(created_at/1000.0) FROM staff_users;
INSERT INTO users(email,display_name,kind,state,legacy_customer_id,preferred_language,created_at,updated_at) SELECT lower(email),name,'customer',CASE WHEN active=0 THEN 'disabled' WHEN email_verified=1 THEN 'active' ELSE 'pending' END,id,language,to_timestamp(created_at/1000.0),to_timestamp(created_at/1000.0) FROM booking_lab_customers;
INSERT INTO users(email,display_name,kind,state) VALUES('bayan@ukrshipping.com','Bayan Biri','staff','invited') ON CONFLICT(email) DO NOTHING;
INSERT INTO user_roles(user_id,role_id) SELECT u.id,r.id FROM users u JOIN staff_users s ON s.id=u.staff_user_id JOIN roles r ON r.code=s.role ON CONFLICT(user_id,role_id) DO NOTHING;
INSERT INTO user_roles(user_id,role_id) SELECT u.id,r.id FROM users u CROSS JOIN roles r WHERE u.email='bayan@ukrshipping.com' AND u.kind='staff' AND r.code='super_admin' ON CONFLICT(user_id,role_id) DO NOTHING;
INSERT INTO customers(user_id,status) SELECT id,CASE WHEN state='disabled' THEN 'disabled' ELSE 'pending' END FROM users WHERE kind='customer';
INSERT INTO customer_companies(legal_name,status,legacy_company_id) SELECT name,CASE WHEN active=1 THEN 'pending' ELSE 'disabled' END,id FROM booking_lab_companies;
INSERT INTO customer_memberships(customer_id,customer_company_id,role,status,approved_at)
 SELECT c.id,co.id,'staff',CASE WHEN m.active=1 AND m.approved=1 THEN 'active' WHEN m.active=0 THEN 'disabled' ELSE 'pending' END,CASE WHEN m.approved=1 THEN now() ELSE NULL END
 FROM booking_lab_memberships m JOIN users u ON u.legacy_customer_id=m.customer_id JOIN customers c ON c.user_id=u.id JOIN customer_companies co ON co.legacy_company_id=m.company_id;
UPDATE customer_companies co SET status='approved' WHERE EXISTS(SELECT 1 FROM customer_memberships m WHERE m.customer_company_id=co.id AND m.status='active');
INSERT INTO user_preferences(user_id,theme_id,language) SELECT u.id,t.id,u.preferred_language FROM users u CROSS JOIN themes t WHERE t.code='ukr-blue';
ALTER TABLE ukr_schema_migrations ADD CONSTRAINT migration_actor_fk FOREIGN KEY(created_by) REFERENCES users(id) ON DELETE RESTRICT;
CREATE INDEX ukr_schema_migrations_actor_idx ON ukr_schema_migrations(created_by);
CREATE INDEX ukr_schema_migrations_created_idx ON ukr_schema_migrations(created_at);
CREATE INDEX ukr_schema_migrations_updated_idx ON ukr_schema_migrations(updated_at);
INSERT INTO task_rules(code,trigger_event,title_template,owner_source,owner_role_id,due_minutes,auto_close_event) SELECT 'approval-review','approval.requested','Review approval {code}','event_role',id,1440,'approval.decided' FROM roles WHERE code='management';
